                   "correlate":  ".di-art[data-art=\"correlate\"]{--paper:#F0F2EF;\n  --paper-2:#E1E5E0;\n  --cb-accent:#2A8FB0;\n  --cb-accent-soft:#D6EAF1;\n  --cb-2:#C9762F;\n  --cb-2-soft:#F4E2D3;\n  --cb-3:#4E6B57;\n  --cb-3-soft:#DFE8DD;\n  --ink:#14191C;\n  --deep:#0E1F28;\n  --cb-deep:#0E1F28;\n  --font-display:\"Courier New\",Consolas,monospace;\n  --hero-align:left;\n  --hero-justify:flex-start;\n  --word-size:96px;\n  --word-size-sm:46px;\n  --hero-bg:radial-gradient(125% 125% at 82% 4%,rgba(42,143,176,0.58) 0%,#0E1F28 48%,rgb(10,22,28) 100%);\n  --hero-ink:#F7F0E4;\n  --hero-word:#FFF8EC;\n  --word-shadow:rgba(42,143,176,0.85);\n  --hero-pad:96px 56px 72px;}\r\n.di-art[data-art=\"correlate\"] .sc-float{animation:correlate__scFloat 5.6s ease-in-out infinite;}\r\n.di-art[data-art=\"correlate\"] .sc-link{fill:none;stroke:var(--sc-dim);stroke-width:1.5;stroke-dasharray:4 5;animation:correlate__scLink 5.6s linear infinite;}\r\n.di-art[data-art=\"correlate\"] .sc-label text{font-family:\"Songti SC\",\"Noto Serif SC\",serif;font-size:10px;font-weight:700;fill:var(--ink);}\r\n@keyframes correlate__scLink{to{stroke-dashoffset:-18;}}\r\n@keyframes correlate__scFloat{0%,100%{transform:translateY(0);}50%{transform:translateY(-6px);}}",
